import { randomBytes } from 'node:crypto';
import { generateKeyBase64 } from '../src/lib/crypto.ts';

/**
 * Prints fresh secrets for a LOCAL .env (development). Production secrets are
 * generated by Render itself (render.yaml → generateValue).
 *   npm run gen:secrets > .env
 * Never paste these values into chats, issues or git.
 */
process.stdout.write(
  [
    '# Local development secrets — generated on this computer, keep private',
    'NODE_ENV=development',
    'PORT=8080',
    `ENCRYPTION_KEY=${generateKeyBase64()}`,
    `SESSION_SECRET=${randomBytes(32).toString('base64')}`,
    `ADMIN_SETUP_TOKEN=${randomBytes(24).toString('base64url')}`,
    '',
  ].join('\n'),
);
